import sys

def max_nice_staircases(x):
    n = 1
    while (n * (n + 1) * (2 * n + 1)) // 6 <= x:
        n += 1
    return n - 1

def main():
    import sys
    input = sys.stdin.read().split()
    t = int(input[0])
    results = []
    index = 1
    for _ in range(t):
        x = int(input[index])
        results.append(max_nice_staircases(x))
        index += 1
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
